# initialization of global variables

our $initialized = 0;

sub check_model_init()
{
    if (!$initialized)
    {
        $initialized = 1;
        %_jm_map_0 = (
            "Point" => \&json_model_5,
            "MultiPoint" => \&json_model_6,
            "LineString" => \&json_model_7,
            "MultiLineString" => \&json_model_8,
            "Polygon" => \&json_model_9,
            "MultiPolygon" => \&json_model_10,
        );
        %_jm_map_1 = (
            "GeometryCollection" => \&json_model_12,
            "Feature" => \&json_model_13,
            "FeatureCollection" => \&json_model_14,
        );
        %check_model_map = (
            "" => \&json_model_1,
            "position" => \&json_model_2,
            "coord_array" => \&json_model_3,
            "linear_ring" => \&json_model_4,
            "Point" => \&json_model_5,
            "MultiPoint" => \&json_model_6,
            "LineString" => \&json_model_7,
            "MultiLineString" => \&json_model_8,
            "Polygon" => \&json_model_9,
            "MultiPolygon" => \&json_model_10,
            "geometry" => \&json_model_11,
            "GeometryCollection" => \&json_model_12,
            "Feature" => \&json_model_13,
            "FeatureCollection" => \&json_model_14,
        );
    }
}

sub check_model_free()
{
    if ($initialized)
    {
        $initialized = 0;
        %_jm_map_0 = ();
        %_jm_map_1 = ();
        %check_model_map = ();
    }
}

sub check_model_mapper($)
{
    my ($name) = @_;
    die "unexpected model name \"$name\"" unless exists $check_model_map{$name};
    return $check_model_map{$name};
}

sub check_model($$$)
{
    my ($json, $name, $rep) = @_;
    die "unexpected model name \"$name\"" unless exists $check_model_map{$name};
    my $path = defined $rep ? [] : undef;
    return $check_model_map{$name}($json, $path, $rep);
}

#
# SCRIPT EXECUTION
#
check_model_init();
jm_main(\&check_model, \%check_model_map, JMC_VERSION);
check_model_free();
